// lib/tools/class-quiz-data.ts (2026-11-07)
//
// The data behind the free "What D&D class should I be?" quiz (/tools/dnd-class-quiz). Generated from
// the quiz Terry supplied; edit here, not in the component.
//
// LICENSING LINE (same as the magic item finder): class, subclass and book names are facts about
// published 5e products, named for reference only. Every description below was written for this quiz;
// none is book text. Partnered books are the D&D Beyond marketplace's third-party publishers. Six Axes
// is not affiliated with Wizards of the Coast or any publisher named here.
//
// Edition codes: "24" 2024 rules, "L" 2014 legacy (official), "14" 2014-era rules (partnered),
// "B" published in both 2014 and 2024 versions.

export type Edition = "24" | "14" | "L" | "B";
export type Role = "melee" | "tank" | "control" | "support" | "ranged" | "skill" | "heal" | "pet";
export type Theme = "martial" | "beast" | "nature" | "cosmic" | "holy" | "death" | "elements" | "luck" | "arcane" | "mind" | "fey" | "shadow" | "eldritch" | "tech" | "infernal" | "blood";
export type Tone = "grim" | "heroic" | "whimsy";

export type Subclass = {
  id: string;
  c: string;      // class key (CLASSES)
  n: string;      // subclass name
  s: string;      // source key (SOURCES)
  e: Edition;
  r: Role[];
  t: Theme[];
  o: Tone;
  b: string;      // our own one-paragraph description
};

export type ClassInfo = { name: string; abilities: string; hitDie: string; complexity: string; blurb: string };
export type Source = { name: string; publisher: string | null };

// A funnel answer: [label, supporting line, target]. Targets: "r:<subclass id>" a result, "c:<class key>"
// that class's tag-built branch, anything else another FUNNEL node.
export type FunnelOption = [string, string, string];
export type FunnelNode = { q: string; s?: string; o: FunnelOption[] };

